// The consumer half of github.com/fboldog/rp2350-amiga src/Host.c,
// unchanged except where marked "frank-amiga". Upstream it drained a ring
// filled by core 0 of the same chip; here the ring is filled by the link
// receiver (stream.c) with the slave's messages, in the same format
// (HostRing.h). Paula's line records arrive in the same ring (MSG_AUDIO).
// Generated by tools/gen_denise_c1.py from the upstream file.

#include "denise.h"
#include "denise_frames.h"
#include "Host.h"
#include "HostRing.h"
#include "../omega/DisplayLayout.h"
#include "../omega/Audio.h"

#include "pico/stdlib.h"
#include "hardware/sync.h"
#include <string.h>

#define SPRITE_X_BIAS 64   // raster x + bias fits the 10-bit field (Host.c)
#define AUDIO_SERVICE() denise_audio_service()

// ── The message ring (filled by stream.c on core 0) ───────────────────────
#ifndef RING_WORDS
#define RING_WORDS 16384u // 64 KB
#endif
#define RING_SPAN (2u * RING_WORDS)
#ifndef OMEGA_RING_SKIP_WORDS
#define OMEGA_RING_SKIP_WORDS (RING_WORDS - MSG_MAX_WORDS)
#endif
static uint32_t ring[RING_WORDS];
static volatile uint32_t ring_head; // published position (stream.c)
static volatile uint32_t ring_tail; // consume position (core 1)

static inline uint32_t ringAdvance(uint32_t pos, uint32_t words) {
    pos += words;
    return pos >= RING_SPAN ? pos - RING_SPAN : pos;
}
static inline uint32_t ringFill(uint32_t head, uint32_t tail) {
    return head >= tail ? head - tail : head + RING_SPAN - tail;
}
static inline uint32_t ringSlot(uint32_t pos) {
    return pos >= RING_WORDS ? pos - RING_WORDS : pos;
}
static volatile uint32_t c1_oldest_frame;
volatile uint32_t denise_audio_lines, denise_audio_long;

uint32_t denise_ring_space(void) {
    return RING_WORDS - ringFill(ring_head, __atomic_load_n(&ring_tail, __ATOMIC_ACQUIRE));
}

void denise_ring_put(const uint32_t *words, uint32_t count) {
    uint32_t head = ring_head;
    uint32_t slot = ringSlot(head);
    for (uint32_t i = 0; i < count; ++i) {
        ring[slot] = words[i];
        if (++slot == RING_WORDS) slot = 0;
    }
    __atomic_store_n(&ring_head, ringAdvance(head, count), __ATOMIC_RELEASE);
    __sev();
}

// ── Core 1: consumer ──────────────────────────────────────────────────────
static uint8_t *c1_image;          // acquired scanout frame, or NULL
static dvi_indexed_frame_t *c1_record; // its segments and palette log
static int c1_open_row;            // last image row with row_segment set
static bool c1_ham;                // the block being placed holds HAM codes
static int c1_first_row;           // image row of raster row 0
static int c1_step;                // raster rows per image row
static int c1_rotation;            // DDF row rotation in raster columns
static bool c1_narrow;             // narrow fetch layout
static int c1_height;              // image rows
static int c1_field;               // interlace field buffer, or -1
static int c1_buffer;              // scanout buffer being drawn
static uint32_t c1_frame_no;       // core 0's frame number
static dvi_indexed_frame_t *c1_prev_record; // the buffer's last frame
static uint32_t c1_buf_frame[2];   // frame each buffer holds (0: none)
static int c1_mark_row;            // last row with a row-end message
static uint16_t c1_mark_pos;       // its palette-log position

// Core 1's loops must not become libc memset/memcpy calls (flash code).
#define C1_FUNC(name) \
    __attribute__((optimize("no-tree-loop-distribute-patterns"))) \
    __not_in_flash_func(name)
static uint16_t c1_palette[32];   // current colours, 0x0RGB
static bool c1_dpf_block;         // frank-amiga: the block being placed is DPF
static void dpfFlush(void);
volatile uint32_t hostCaptureHold; // debug: non-zero stops drawing new frames



// Table-driven planar-to-index: c2p_spread[b] holds the 8 pixels of plane
// byte b as bytes 0/1 (leftmost pixel = bit 7 = lowest byte), so OR-ing the
// entries of all planes, shifted by plane number, yields 8 colour indices
// at once. Pixel order matches *Planar2Chunky: bits 7..0 of the low byte of
// each plane word first, then bits 15..8.
static uint32_t c2p_spread[256][2];

static void hostInitPlanarTables(void) {
    for (int b = 0; b < 256; ++b) {
        uint32_t lo = 0, hi = 0;
        for (int k = 0; k < 4; ++k) {
            lo |= (uint32_t)((b >> (7 - k)) & 1) << (8 * k);
            hi |= (uint32_t)((b >> (3 - k)) & 1) << (8 * k);
        }
        c2p_spread[b][0] = lo;
        c2p_spread[b][1] = hi;
    }
}

#define C2P(p, shift, half) c2p_spread[((p) >> (shift)) & 0xffu][half]

static void C1_FUNC(c1Record)(int y, int x0, int x1);

// Sprite pixels for the right edge of a rotated row: those columns come
// from the next beam line's first fetch, after the row's sprites, so the
// pixels wait here (colour, 0x80: behind) until the row is left.
static uint8_t c1_tail[OMEGA_DDF_ROTATED_PIXELS];
static bool c1_tail_pending;

// The columns already drawn on the open row y.
static void __attribute__((noinline)) C1_FUNC(c1DrawnRange)(int y, int *min, int *max) {
    const dvi_indexed_frame_t *rec = c1_record;
    const uint32_t used = rec->segments_used;
    *min = DVI_DIRECT_IMAGE_WIDTH;
    *max = 0;
    for (uint32_t i = rec->row_segment[y]; i < used; ++i) {
        const int x0 = (int)DVI_SEGMENT_X0(rec->segment[i]);
        const int x1 = (int)DVI_SEGMENT_X1(rec->segment[i]);
        if (x0 < *min) *min = x0;
        if (x1 > *max) *max = x1;
    }
    if (*min > *max)
        *min = *max = 0;  // nothing drawn on this row yet
}

// Puts one sprite pixel on the open row y. Columns the bitplanes did not
// draw get colour 0 first and are recorded as drawn.
static void __attribute__((noinline)) C1_FUNC(c1SpritePixel)(int y, int ix, uint8_t colour,
                                   bool behind, int *min, int *max) {
    uint8_t *line = c1_image + y * DVI_DIRECT_IMAGE_WIDTH;
    if (ix < *min || ix >= *max) {
        // Outside the drawn columns: extend the row's drawn range with
        // colour 0 up to this pixel, keeping it contiguous.
        int x0, x1;
        if (*min == *max) { x0 = ix; x1 = ix + 1; }
        else if (ix < *min) { x0 = ix; x1 = *min; }
        else { x0 = *max; x1 = ix + 1; }
        for (int k = x0; k < x1; ++k)
            line[k] = 0;
        const bool ham = c1_ham;
        c1_ham = false;
        c1Record(y, x0, x1);
        c1_ham = ham;
        if (*min == *max) { *min = x0; *max = x1; }
        else if (x0 < *min) *min = x0;
        else *max = x1;
    }
    // Behind the playfield: only over colour 0 (or other sprites).
    if (behind && line[ix] != 0 && !(line[ix] & 0x40u))
        return;
    line[ix] = colour;
}

// Draws the open row's waiting right-edge sprite pixels; called before
// the open row advances.
static void C1_FUNC(c1SpriteTailFlush)(void) {
    c1_tail_pending = false;
    const int y = c1_open_row;
    const bool on_row = c1_image && y >= 0 && y < c1_height;
    const int x0 = DVI_DIRECT_IMAGE_WIDTH - OMEGA_DDF_ROTATED_PIXELS;
    int min = 0, max = 0;
    if (on_row)
        c1DrawnRange(y, &min, &max);
    for (int k = 0; k < OMEGA_DDF_ROTATED_PIXELS; ++k) {
        const uint8_t v = c1_tail[k];
        if (!v)
            continue;
        c1_tail[k] = 0;
        if (on_row)
            c1SpritePixel(y, x0 + k, v & 0x7fu, (v & 0x80u) != 0, &min, &max);
    }
}

// Overlays a sprite on image row y (core 0 has clipped it to the display
// window). Sprite pixels carry 0x40: scanout shows them as colour
// registers even on HAM rows, where they must not change the held colour.
static void C1_FUNC(c1Sprite)(int row, int x, uint32_t extra, uint32_t ab,
                              uint32_t cd) {
    dpfFlush();
    if (!c1_image || row % c1_step)
        return;
    const int y = c1_first_row + row / c1_step;
    if (y < 0 || y >= c1_height || y != c1_open_row)
        return;
    int min, max;
    c1DrawnRange(y, &min, &max);
    const int tail_x0 = DVI_DIRECT_IMAGE_WIDTH - c1_rotation;
    const uint32_t base = extra & 0x1fu;
    const bool attached = (extra >> 5) & 1u;
    const bool behind = (extra >> 6) & 1u;
    for (int i = 0; i < 16; ++i) {
        const int bit = 15 - i;
        uint32_t v = ((ab >> bit) & 1u) | ((ab >> (15 + bit)) & 2u);
        if (attached)
            v |= ((cd >> bit) & 1u) << 2 | ((cd >> (16 + bit)) & 1u) << 3;
        if (!v)
            continue;
        const uint8_t colour = (uint8_t)(0x40u | (base + v));
        for (int j = 0; j < 2; ++j) {
            int ix = x + 2 * i + j;
            if (c1_narrow) {
                ix -= HOST_FETCH_LEAD;
            } else {
                // x is a raster column; past HOST_RASTER_W it continues
                // into the right edge of a rotated row.
                if (ix < 0 || ix >= HOST_RASTER_W + c1_rotation)
                    continue;
                ix -= c1_rotation;
            }
            if (ix < 0 || ix >= DVI_DIRECT_IMAGE_WIDTH)
                continue;
            if (c1_rotation && ix >= tail_x0) {
                c1_tail[ix - tail_x0] = (uint8_t)(colour | (behind ? 0x80u : 0u));
                c1_tail_pending = true;
                continue;
            }
            c1SpritePixel(y, ix, colour, behind, &min, &max);
        }
    }
}

// Records that image columns [x0, x1) of row y were drawn with the palette
// as logged so far. Runs drawn back to back with no palette change between
// them merge.
static void C1_FUNC(c1Record)(int y, int x0, int x1) {
    if (c1_tail_pending && y > c1_open_row)
        c1SpriteTailFlush();
    dvi_indexed_frame_t *rec = c1_record;
    const uint32_t used = rec->segments_used;
    // Rows arrive in beam order; a row behind the open one (e.g. after a
    // mid-frame DIWSTRT change) cannot be filed any more.
    if (y < c1_open_row)
        return;
    while (c1_open_row < y)
        rec->row_segment[++c1_open_row] = (uint16_t)used;
    const uint32_t pos = rec->log_used;
    if (used > rec->row_segment[y]) {
        uint32_t *last = &rec->segment[used - 1u];
        if (DVI_SEGMENT_X1(*last) == (uint32_t)x0 &&
            DVI_SEGMENT_POS(*last) == pos &&
            DVI_SEGMENT_HAM(*last) == (uint32_t)c1_ham) {
            *last = DVI_SEGMENT(DVI_SEGMENT_X0(*last), x1, pos, c1_ham);
            return;
        }
    }
    if (used == DVI_MAX_SEGMENTS) {
        rec->segment_overflow = true;
        return;
    }
    rec->segment[used] = DVI_SEGMENT(x0, x1, pos, c1_ham);
    rec->segments_used = (uint16_t)(used + 1u);
}

// frank-amiga: dual playfield. A DPF block is split into its playfields
// (planes 1/3/5 -> PF1, colours 0-7; planes 2/4/6 -> PF2, colours 8-15),
// each kept in a row buffer at its own scroll offset; they are combined by
// priority when the row is flushed (before anything else touches it).
static uint8_t dpf_pf1[DVI_DIRECT_IMAGE_WIDTH], dpf_pf2[DVI_DIRECT_IMAGE_WIDTH];
static int dpf_y = -1, dpf_min, dpf_max;
static int c1_dpf_delta;          // PF2 offset from PF1, image columns
static bool c1_pf2pri;
static void C1_FUNC(c1Record)(int y, int x0, int x1);

// Colour numbers of a 6-bit DPF pixel: its playfields (0-7 each) and the
// combined colour by priority (PF2PRI: 1 = PF2 in front).
static uint8_t dpf_lut1[64], dpf_lut2[64], dpf_comp[2][64];
static void C1_FUNC(dpfTables)(void) {
    for (int v = 0; v < 64; ++v) {
        const uint8_t a = (uint8_t)((v & 1) | ((v >> 1) & 2) | ((v >> 2) & 4));
        const uint8_t b = (uint8_t)(((v >> 1) & 1) | ((v >> 2) & 2) | ((v >> 3) & 4));
        dpf_lut1[v] = a;
        dpf_lut2[v] = b;
        dpf_comp[0][v] = a ? a : (b ? (uint8_t)(8u + b) : 0);
        dpf_comp[1][v] = b ? (uint8_t)(8u + b) : a;
    }
}

static void __attribute__((noinline)) C1_FUNC(dpfFlush)(void) {
    if (dpf_y < 0)
        return;
    const int y = dpf_y;
    dpf_y = -1;
    if (!c1_image || dpf_max <= dpf_min)
        return;
    uint8_t *line = c1_image + y * DVI_DIRECT_IMAGE_WIDTH;
    const uint8_t *comp = dpf_comp[c1_pf2pri];
    for (int x = dpf_min; x < dpf_max; ++x) {
        // Recombine the playfields into a 6-bit pixel for the table.
        const uint8_t a = dpf_pf1[x], b = dpf_pf2[x];
        line[x] = comp[(a & 1) | (b & 1) << 1 | (a & 2) << 1 | (b & 2) << 2 |
                       (a & 4) << 2 | (b & 4) << 3];
        dpf_pf1[x] = dpf_pf2[x] = 0;
    }
    const bool ham = c1_ham;
    c1_ham = false;
    c1Record(y, dpf_min, dpf_max);
    c1_ham = ham;
}

// Clips [x, x + width) of a block to the image; returns the first index.
static inline int C1_FUNC(dpfClip)(int x, int width, int *end) {
    int i0 = x < 0 ? -x : 0;
    int i1 = width;
    if (x + i1 > DVI_DIRECT_IMAGE_WIDTH)
        i1 = DVI_DIRECT_IMAGE_WIDTH - x;
    *end = i1;
    return i0;
}

static void C1_FUNC(dpfPlace)(int y, int image_x, const uint8_t *pixels,
                              int width) {
    static bool ready;
    if (!ready) {
        dpfTables();
        ready = true;
    }
    if (y != dpf_y)
        dpfFlush();
    // Playfields at the same scroll (the usual case): combine straight into
    // the row.
    if (c1_dpf_delta == 0 && dpf_y < 0) {
        int i1;
        const int i0 = dpfClip(image_x, width, &i1);
        if (i1 <= i0)
            return;
        uint8_t *line = c1_image + y * DVI_DIRECT_IMAGE_WIDTH + image_x;
        const uint8_t *comp = dpf_comp[c1_pf2pri];
        for (int i = i0; i < i1; ++i)
            line[i] = comp[pixels[i]];
        const bool ham = c1_ham;
        c1_ham = false;
        c1Record(y, image_x + i0, image_x + i1);
        c1_ham = ham;
        return;
    }
    if (y != dpf_y) {
        dpf_y = y;
        dpf_min = DVI_DIRECT_IMAGE_WIDTH;
        dpf_max = 0;
    }
    int i1;
    int i0 = dpfClip(image_x, width, &i1);
    if (i1 > i0) {
        for (int i = i0; i < i1; ++i)
            dpf_pf1[image_x + i] = dpf_lut1[pixels[i]];
        if (image_x + i0 < dpf_min) dpf_min = image_x + i0;
        if (image_x + i1 > dpf_max) dpf_max = image_x + i1;
    }
    const int x2 = image_x + c1_dpf_delta;
    i0 = dpfClip(x2, width, &i1);
    if (i1 > i0) {
        for (int i = i0; i < i1; ++i)
            dpf_pf2[x2 + i] = dpf_lut2[pixels[i]];
        if (x2 + i0 < dpf_min) dpf_min = x2 + i0;
        if (x2 + i1 > dpf_max) dpf_max = x2 + i1;
    }
}

static inline void C1_FUNC(c1Copy)(uint8_t *line,
                                               const uint8_t *pixels,
                                               int y, int x, int count) {
    for (int i = 0; i < count; ++i)
        line[x + i] = pixels[i];
    c1Record(y, x, x + count);
}

// Places `width` colour numbers of raster (row, x) into the scanout frame.
static void C1_FUNC(c1Place)(int row, int x,
                                         const uint8_t *pixels, int width) {
    if (!c1_image || row % c1_step)
        return;
    const int y = c1_first_row + row / c1_step;
    if (y < 0 || y >= c1_height)
        return;
    uint8_t *line = c1_image + y * DVI_DIRECT_IMAGE_WIDTH;
    if (c1_narrow) {
        int image_x = x - HOST_FETCH_LEAD;
        int first = 0, count = width;
        if (image_x < HOST_VISIBLE_X0) {
            first = HOST_VISIBLE_X0 - image_x;
            image_x = HOST_VISIBLE_X0;
        }
        if (image_x + (count - first) > HOST_VISIBLE_X1)
            count = first + HOST_VISIBLE_X1 - image_x;
        if (count > first)
            c1Copy(line, pixels + first, y, image_x, count - first);
        return;
    }
    int image_x = x - c1_rotation;
    if (image_x < 0)
        image_x += HOST_RASTER_W;
    if (c1_dpf_block) {
        dpfPlace(y, image_x, pixels, width);
        return;
    }
    if (dpf_y >= 0)
        dpfFlush();
    int first = HOST_RASTER_W - image_x;
    if (first > width)
        first = width;
    c1Copy(line, pixels, y, image_x, first);
    // The block wraps around a rotated row; elsewhere it is clipped at the
    // right edge (fine scroll pushes the last block past it).
    if (first < width && c1_rotation)
        c1Copy(line, pixels + first, y, 0, width - first);
}

static void C1_FUNC(c1Hires)(int row, int x, uint32_t p12,
                                         uint32_t p34) {
    const uint16_t p1 = (uint16_t)p12, p2 = (uint16_t)(p12 >> 16);
    const uint16_t p3 = (uint16_t)p34, p4 = (uint16_t)(p34 >> 16);
    uint8_t pixels[16];
    for (int half = 0; half < 2; ++half) {
        const int shift = half * 8;
        for (int part = 0; part < 2; ++part) {
            uint32_t index = C2P(p1, shift, part) |
                             C2P(p2, shift, part) << 1 |
                             C2P(p3, shift, part) << 2 |
                             C2P(p4, shift, part) << 3;
            uint8_t *out = pixels + half * 8 + part * 4;
            out[0] = (uint8_t)index;
            out[1] = (uint8_t)(index >> 8);
            out[2] = (uint8_t)(index >> 16);
            out[3] = (uint8_t)(index >> 24);
        }
    }
    c1_ham = false;
    c1Place(row, x, pixels, 16);
}

// LORES: 16 pixels of up to 6 planes (EHB palette 32..63, or HAM codes),
// each doubled.
static void C1_FUNC(c1Lores)(int row, int x, uint32_t p12,
                                         uint32_t p34, uint32_t p56,
                                         bool ham) {
    const uint16_t p1 = (uint16_t)p12, p2 = (uint16_t)(p12 >> 16);
    const uint16_t p3 = (uint16_t)p34, p4 = (uint16_t)(p34 >> 16);
    const uint16_t p5 = (uint16_t)p56, p6 = (uint16_t)(p56 >> 16);
    uint8_t pixels[32];
    for (int half = 0; half < 2; ++half) {
        const int shift = half * 8;
        for (int part = 0; part < 2; ++part) {
            uint32_t index = C2P(p1, shift, part) |
                             C2P(p2, shift, part) << 1 |
                             C2P(p3, shift, part) << 2 |
                             C2P(p4, shift, part) << 3 |
                             C2P(p5, shift, part) << 4 |
                             C2P(p6, shift, part) << 5;
            uint8_t *out = pixels + half * 16 + part * 8;
            for (int k = 0; k < 4; ++k) {
                const uint8_t colour = (uint8_t)(index >> (8 * k));
                out[2 * k] = colour;
                out[2 * k + 1] = colour;
            }
        }
    }
    c1_ham = ham;
    c1Place(row, x, pixels, 32);
}

static void C1_FUNC(c1Begin)(uint32_t layout, uint32_t size,
                             uint32_t frame_no) {
    c1_frame_no = frame_no;
    c1_first_row = (int16_t)(layout & 0xffffu);
    c1_step = (int)((layout >> 16) & 0xffu);
    c1_narrow = (layout >> 24) & 1u;
    c1_rotation = (int)(size & 0xffffu);
    c1_height = (int)(size >> 16);
    // Field buffer: 0 for the short field (even output lines), 1 for the
    // long one (odd lines). The other way round, diagonal strokes in
    // Agony's interlaced intro zigzagged by a pixel.
    c1_field = (layout >> 25) & 1u ? (int)((layout >> 26) & 1u) : -1;
    if (c1_field >= 0) {
        // Interlace: draw the field over its own buffer, no swap to wait
        // for (scanout weaves both buffers).
        c1_image = hostCaptureHold ? NULL
                 : dvi_display_field_acquire(c1_field, &c1_record,
                                             &c1_prev_record);
        c1_buffer = c1_field;
    } else {
        dvi_display_weave_stop();
        // The previous frame may still wait for the next DVI frame boundary
        // (at most one display frame). Wait for the swap while core 0 keeps
        // queueing; if the ring gets close to full first, skip this frame so
        // the emulator never stalls. A finished frame is never discarded.
        while (dvi_display_frame_pending() &&
               ringFill(ring_head, ring_tail) < OMEGA_RING_SKIP_WORDS)
            AUDIO_SERVICE();
        // hostCaptureHold (set over SWD) freezes the displayed frame so it can
        // be dumped consistently; emulation keeps running.
        c1_image = dvi_display_frame_pending() || hostCaptureHold
                 ? NULL
                 : dvi_display_direct_acquire(&c1_record, &c1_prev_record,
                                              &c1_buffer); // NULL: boot pattern
    }
    if (!c1_image)
        return;
    dvi_indexed_frame_t *rec = c1_record;
    for (int i = 0; i < 32; ++i)
        rec->initial_palette[i] = c1_palette[i];
    rec->segments_used = 0;
    rec->log_used = 0;
    rec->segment_overflow = false;
    if (c1_tail_pending) {
        c1_tail_pending = false;  // left by a frame that was not drawn
        for (int k = 0; k < OMEGA_DDF_ROTATED_PIXELS; ++k)
            c1_tail[k] = 0;
    }
    c1_open_row = -1;
    c1_mark_row = -1;
    c1_mark_pos = 0;
}

// Image row `row` is unchanged since a frame this buffer holds: its pixels
// are in place; take its runs from the buffer's last record, at the current
// colour-log position (the palette may have changed since).
static void C1_FUNC(c1RowSame)(int row) {
    dpfFlush();
    if (!c1_image || row % c1_step)
        return;
    const int y = c1_first_row + row / c1_step;
    if (y < c1_open_row || y >= c1_height)
        return;
    if (c1_tail_pending && y > c1_open_row)
        c1SpriteTailFlush();
    dvi_indexed_frame_t *rec = c1_record;
    const dvi_indexed_frame_t *old = c1_prev_record;
    uint32_t used = rec->segments_used;
    while (c1_open_row < y)
        rec->row_segment[++c1_open_row] = (uint16_t)used;
    uint32_t first = old->row_segment[y], last = old->row_segment[y + 1];
    if (last > old->segments_used)
        last = old->segments_used;
    const uint32_t pos = rec->log_used;
    for (uint32_t i = first; i < last; ++i) {
        if (used == DVI_MAX_SEGMENTS) {
            rec->segment_overflow = true;
            break;
        }
        const uint32_t seg = old->segment[i];
        rec->segment[used++] = DVI_SEGMENT(DVI_SEGMENT_X0(seg),
                                           DVI_SEGMENT_X1(seg), pos,
                                           DVI_SEGMENT_HAM(seg));
    }
    rec->segments_used = (uint16_t)used;
}

// Image row `row` has ended: a row without drawn runs shows the colours
// logged so far.
// Rows since the previous message saw no palette change: they keep its
// position.
static void C1_FUNC(c1RowEnd)(int row) {
    dpfFlush();
    if (!c1_image || row % c1_step)
        return;
    const int y = c1_first_row + row / c1_step;
    if (y <= c1_mark_row || y >= c1_height)
        return;
    dvi_indexed_frame_t *rec = c1_record;
    while (++c1_mark_row < y)
        rec->row_log[c1_mark_row] = c1_mark_pos;
    c1_mark_pos = rec->log_used;
    rec->row_log[y] = c1_mark_pos;
}

// Unwritten columns need no fill: scanout shows them in the row's COLOR00.
static void C1_FUNC(c1End)(uint16_t border) {
    dpfFlush();
    if (!c1_image)
        return;
    if (c1_tail_pending)
        c1SpriteTailFlush();
    dvi_indexed_frame_t *rec = c1_record;
    while (c1_open_row < DVI_MAX_ROWS)
        rec->row_segment[++c1_open_row] = rec->segments_used;
    while (++c1_mark_row < c1_height)
        rec->row_log[c1_mark_row] = c1_mark_pos;
    if (c1_field >= 0)
        dvi_display_field_publish(border);
    else
        dvi_display_direct_publish(border);
    // Core 0 leaves out a row unchanged since the oldest frame either
    // buffer holds.
    c1_buf_frame[c1_buffer] = c1_frame_no;
    const uint32_t a = c1_buf_frame[0], b = c1_buf_frame[1];
    __atomic_store_n(&c1_oldest_frame,
                     !a || !b ? 0u : (int32_t)(a - b) < 0 ? a : b,
                     __ATOMIC_RELEASE);
    c1_image = NULL;
}

// Takes the new colours and logs the changed ones for the frame being drawn.
static void C1_FUNC(c1Palette)(const uint32_t *pairs) {
    dvi_indexed_frame_t *rec = c1_record;
    for (uint32_t i = 0; i < 16u; ++i) {
        const uint32_t pair = pairs[i];
        for (uint32_t k = 0; k < 2u; ++k) {
            const uint32_t reg = 2u * i + k;
            const uint16_t colour = (uint16_t)(pair >> (16u * k));
            if (colour == c1_palette[reg])
                continue;
            c1_palette[reg] = colour;
            if (!c1_image)
                continue;
            // Before any row: the frame's starting palette. A full log
            // drops the change for this frame; the next frame starts from
            // the complete palette again.
            if (c1_open_row < 0 && c1_mark_row < 0)
                rec->initial_palette[reg] = colour;
            else if (rec->log_used < DVI_MAX_PALETTE_LOG)
                rec->palette_log[rec->log_used++] = reg << 12 | colour;
        }
    }
}


// Image column of raster column x (as c1Place() maps it).
static inline int C1_FUNC(c1ImageX)(int x) {
    if (c1_narrow)
        return x - HOST_FETCH_LEAD;
    int image_x = x - c1_rotation;
    if (image_x < 0)
        image_x += HOST_RASTER_W;
    return image_x;
}

// Colour register `reg` changed at raster column x of row `row`: log it,
// and the row shows it from x on. Runs drawn before the change that reach
// x take the new colour from there (a run spanning x is split). If x is
// right of the row's runs, or the row has none yet (a border line), the
// undrawn rest of the row becomes a run of colour 0 (COLOR00) first, so
// Copper colour changes show in the border too (ATK's colour bars).
static void C1_FUNC(c1Colour)(int row, int x, int reg, uint16_t value) {
    dpfFlush();
    if (value == c1_palette[reg])
        return;
    c1_palette[reg] = value;
    dvi_indexed_frame_t *rec = c1_record;
    if (!c1_image || rec->log_used >= DVI_MAX_PALETTE_LOG)
        return;
    const int y = row % c1_step ? -1 : c1_first_row + row / c1_step;
    const bool on_row = y >= 0 && y < c1_height && y >= c1_open_row;
    if (c1_tail_pending && on_row && y > c1_open_row)
        c1SpriteTailFlush();
    int c = c1ImageX(x);
    if (c < 0)
        c = 0;
    uint32_t used = rec->segments_used;
    if (on_row && c < DVI_DIRECT_IMAGE_WIDTH) {
        uint32_t start = 0;
        if (y == c1_open_row) {
            for (uint32_t i = rec->row_segment[y]; i < used; ++i)
                if (DVI_SEGMENT_X1(rec->segment[i]) > start)
                    start = DVI_SEGMENT_X1(rec->segment[i]);
        } else {
            while (c1_open_row < y)
                rec->row_segment[++c1_open_row] = (uint16_t)used;
        }
        if ((uint32_t)c >= start && start < DVI_DIRECT_IMAGE_WIDTH &&
            used < DVI_MAX_SEGMENTS) {
            uint8_t *line = c1_image + y * DVI_DIRECT_IMAGE_WIDTH;
            for (uint32_t i = start; i < DVI_DIRECT_IMAGE_WIDTH; ++i)
                line[i] = 0;
            rec->segment[used++] =
                DVI_SEGMENT(start, DVI_DIRECT_IMAGE_WIDTH, rec->log_used, 0);
        }
    }
    rec->palette_log[rec->log_used++] = (uint32_t)reg << 12 | value;
    const uint32_t pos = rec->log_used;
    if (!on_row || y != c1_open_row) {
        rec->segments_used = (uint16_t)used;
        return;
    }
    for (uint32_t i = rec->row_segment[c1_open_row]; i < used; ++i) {
        const uint32_t seg = rec->segment[i];
        const uint32_t x0 = DVI_SEGMENT_X0(seg), x1 = DVI_SEGMENT_X1(seg);
        const uint32_t ham = DVI_SEGMENT_HAM(seg);
        if (x1 <= (uint32_t)c)
            continue;
        if (x0 >= (uint32_t)c) {
            rec->segment[i] = DVI_SEGMENT(x0, x1, pos, ham);
            continue;
        }
        if (used == DVI_MAX_SEGMENTS)
            continue;               // no room to split: keeps the old colour
        for (uint32_t j = used; j > i + 1u; --j)
            rec->segment[j] = rec->segment[j - 1u];
        rec->segment[i] = DVI_SEGMENT(x0, (uint32_t)c, DVI_SEGMENT_POS(seg), ham);
        rec->segment[i + 1u] = DVI_SEGMENT((uint32_t)c, x1, pos, ham);
        ++used;
        ++i;
    }
    rec->segments_used = (uint16_t)used;
}

void C1_FUNC(hostCore1Loop)(void) {
    uint32_t tail = ring_tail;
    for (;;) {
        uint32_t head;
        while ((head = __atomic_load_n(&ring_head, __ATOMIC_ACQUIRE)) == tail) {
            AUDIO_SERVICE();   // HDMI audio stretching between messages
            __wfe();
        }
        unsigned since_audio = 0;
        while (tail != head) {
            if (++since_audio == 32u) {   // keep the audio output ring fed
                since_audio = 0;
                AUDIO_SERVICE();
            }
            // Messages are read in place; only one that may wrap around
            // the end of the ring is first copied out (MSG_MAX_WORDS: the
            // longest).
            uint32_t slot = ringSlot(tail);
            const uint32_t *msg = &ring[slot];
            uint32_t wrapped[MSG_MAX_WORDS];
            if (slot + MSG_MAX_WORDS > RING_WORDS) {
                for (uint32_t i = 0; i < MSG_MAX_WORDS; ++i) {
                    wrapped[i] = ring[slot];
                    if (++slot == RING_WORDS)
                        slot = 0;
                }
                msg = wrapped;
            }
            const uint32_t header = msg[0];
            const int type = (int)(header & 0xfu);
            const int row = (int)((header >> 4) & 0x1ffu);
            const int x = (int)((header >> 13) & 0x3ffu);
            uint32_t length;
            switch (type) {
            case MSG_DPF: {
                const uint32_t st = header >> 23;
                dpfFlush();
                c1_dpf_delta = 2 * ((int)((st & 31u) ^ 16u) - 16);
                c1_pf2pri = (st >> 5) & 1u;
                length = 1;
                break;
            }
            case MSG_HIRES: {
                const int count = (int)(header >> MSG_RUN_SHIFT & 0xfu) + 1;
                c1_dpf_block = (header & MSG_RUN_DPF) != 0;
                for (int i = 0; i < count; ++i)
                    c1Hires(row, x + 16 * i, msg[1 + 2 * i], msg[2 + 2 * i]);
                length = 1 + 2 * (uint32_t)count;
                break;
            }
            case MSG_LORES: {
                const int count = (int)(header >> MSG_RUN_SHIFT & 0xfu) + 1;
                c1_dpf_block = (header & MSG_RUN_DPF) != 0;
                const bool ham = (header >> 23) & 1u;
                for (int i = 0; i < count; ++i)
                    c1Lores(row, x + 32 * i, msg[1 + 3 * i], msg[2 + 3 * i],
                            msg[3 + 3 * i], ham);
                length = 1 + 3 * (uint32_t)count;
                break;
            }
            case MSG_PALETTE:
                c1Palette(&msg[1]);
                length = 17;
                break;
            case MSG_COLOUR:
                c1Colour(row, x, (int)(header >> 23 & 31u), (uint16_t)msg[1]);
                length = 2;
                break;
            case MSG_BEGIN:
                c1Begin(msg[1], msg[2], msg[3]);
                length = 4;
                break;
            case MSG_ROW_SAME:
                c1RowSame(row);
                length = 1;
                break;
            case MSG_SPRITE:
                c1Sprite(row, x - SPRITE_X_BIAS, header >> 23, msg[1], msg[2]);
                length = ((header >> 28) & 1u) ? 3 : 2;
                break;
            case MSG_END:
                c1End((uint16_t)msg[1]);
                length = 2;
                break;
            case MSG_ROW_END:
                c1RowEnd(row);
                length = 1;
                break;
            case MSG_AUDIO: {
                // frank-amiga: Paula's line record (omega/Audio.h), mixed
                // here (omega/AudioMix.c) into the I2S output.
                const uint32_t n = header >> 23;
                denise_audio_lines++;
                if (n <= AUDIO_LINE_MAX_WORDS) {
                    uint32_t words[AUDIO_LINE_MAX_WORDS];
                    uint32_t s = ringSlot(tail);
                    for (uint32_t i = 0; i < n; ++i) {
                        if (++s == RING_WORDS) s = 0;
                        words[i] = ring[s];
                    }
                    if (words[0] & AUDIO_LINE_LONG) denise_audio_long++;
                    audioMixLine(words, (int)n);
                }
                length = 1 + n;
                break;
            }
            default:
                // frank-amiga: a corrupt stream (lost link data). Drop
                // everything queued; stream.c resynchronises at a frame.
                denise_stream_corrupt(header);
                head = __atomic_load_n(&ring_head, __ATOMIC_ACQUIRE);
                tail = head;
                __atomic_store_n(&ring_tail, tail, __ATOMIC_RELEASE);
                c1_image = NULL;
                continue;
            }
            tail = ringAdvance(tail, length);
            __atomic_store_n(&ring_tail, tail, __ATOMIC_RELEASE);
        }
    }
}

void denise_c1_init(void) {
    hostInitPlanarTables();
}
